//! Generated by `ofm-packages/avatar/build_portraits.py build` from `faces.csv`.
//! Do not edit by hand: re-tag the face in the CSV and rebuild.

use super::{AgeBand, AppearanceGroup, PortraitFace};

macro_rules! face {
    ($id:literal, $group:ident, $band:ident) => {
        PortraitFace {
            id: $id,
            group: AppearanceGroup::$group,
            band: AgeBand::$band,
            bytes: include_bytes!(concat!("../../../assets/portrait-sources/", $id, ".webp")),
        }
    };
}

